"use client";

import { useId, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { Avatar } from "@/components/kit/base/avatar";
import { Popover, type PopoverAlign } from "@/components/kit/popover";

const cx = (...c: (string | false | null | undefined)[]) => c.filter(Boolean).join(" ");
const CURVE = "cubic-bezier(.16,1,.3,1)";

export interface NotificationEntry {
  id: string;
  title: string;
  body?: string;
  time: Date;
  read?: boolean;
  /** Who did it. Shows their avatar; without it a neutral bell is shown. */
  actor?: { name: string; src?: string };
}

export interface NotificationCenterProps {
  /** Controlled list. Pass with `onNotificationsChange`. */
  notifications?: NotificationEntry[];
  defaultNotifications?: NotificationEntry[];
  onNotificationsChange?: (notifications: NotificationEntry[]) => void;
  /** Called when a notification is clicked. It's marked read first. */
  onOpenItem?: (notification: NotificationEntry) => void;
  /** Override "now" for grouping and relative times. */
  now?: Date;
  locale?: string;
  align?: PopoverAlign;
  label?: string;
  className?: string;
}

const KEYFRAMES = `@keyframes kit-nc-ring { 0%, 100% { transform: rotate(0) } 15% { transform: rotate(14deg) } 30% { transform: rotate(-11deg) } 45% { transform: rotate(7deg) } 60% { transform: rotate(-4deg) } 75% { transform: rotate(2deg) } }
@keyframes kit-nc-count { from { opacity: 0; transform: translateY(70%) } }
@keyframes kit-nc-badge { from { opacity: 0; transform: scale(.4) } }
@keyframes kit-nc-in { from { opacity: 0; transform: translateY(6px) } }
@media (prefers-reduced-motion: reduce) { .kit-nc, .kit-nc * { animation: none !important; transition-duration: 0s !important; } }`;

const DAY = 86_400_000;
const day0 = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();

function BellIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 20 20" className={className} fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M5 8a5 5 0 0 1 10 0c0 4 1.5 5.5 1.5 5.5h-13S5 12 5 8Z" />
      <path d="M8.5 16.5a1.6 1.6 0 0 0 3 0" />
    </svg>
  );
}

/* ---------- the panel (mounted while open) ---------- */

function Panel({
  items,
  update,
  onOpenItem,
  now,
  locale,
  label,
}: {
  items: NotificationEntry[];
  update: (next: NotificationEntry[]) => void;
  onOpenItem?: (n: NotificationEntry) => void;
  now: Date;
  locale?: string;
  label: string;
}) {
  const [tab, setTab] = useState<"all" | "unread">("all");
  // What was unread when the Unread tab opened stays listed, so rows don't vanish as you read them.
  const [snap, setSnap] = useState<Set<string>>(() => new Set());
  const [status, setStatus] = useState("");
  const list = useRef<HTMLUListElement>(null);
  const tabsId = useId();

  const unread = items.filter((n) => !n.read).length;
  const shown = tab === "all" ? items : items.filter((n) => !n.read || snap.has(n.id));

  const fmt = useMemo(
    () => ({
      date: new Intl.DateTimeFormat(locale, { weekday: "short", month: "short", day: "numeric" }),
      clock: new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" }),
    }),
    [locale],
  );

  const groups = useMemo(() => {
    const today = day0(now);
    const out: { label: string; items: NotificationEntry[] }[] = [];
    for (const n of [...shown].sort((a, b) => b.time.getTime() - a.time.getTime())) {
      const d = day0(n.time);
      const label = d === today ? "Today" : d === today - DAY ? "Yesterday" : fmt.date.format(n.time);
      const g = out[out.length - 1];
      if (g?.label === label) g.items.push(n);
      else out.push({ label, items: [n] });
    }
    return out;
  }, [shown, now, fmt]);

  const ago = (t: Date) => {
    const s = Math.max(0, (now.getTime() - t.getTime()) / 1000);
    if (s < 60) return "now";
    if (s < 3600) return `${Math.floor(s / 60)}m`;
    if (day0(t) === day0(now)) return `${Math.floor(s / 3600)}h`;
    return fmt.clock.format(t);
  };

  const markRead = (ids: string[]) => {
    const set = new Set(ids);
    if (!items.some((n) => set.has(n.id) && !n.read)) return;
    update(items.map((n) => (set.has(n.id) ? { ...n, read: true } : n)));
  };

  const pickTab = (t: "all" | "unread") => {
    if (t === "unread") setSnap(new Set(items.filter((n) => !n.read).map((n) => n.id)));
    setTab(t);
  };

  const onListKey = (e: KeyboardEvent) => {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
    const rows = [...(list.current?.querySelectorAll<HTMLElement>("[data-nc-item]") ?? [])];
    if (!rows.length) return;
    e.preventDefault();
    const i = rows.indexOf(document.activeElement as HTMLElement);
    const next = e.key === "Home" ? 0 : e.key === "End" ? rows.length - 1 : Math.min(rows.length - 1, Math.max(0, i + (e.key === "ArrowDown" ? 1 : -1)));
    rows[next]?.focus();
  };

  return (
    <div className="flex max-h-[min(520px,calc(100vh-96px))] flex-col">
      <p className="sr-only" aria-live="polite">
        {status}
      </p>
      <div className="flex items-center justify-between gap-3 px-4 pb-2 pt-3.5">
        <h3 className="text-[14px] font-medium tracking-[-0.01em] text-ink">{label}</h3>
        <button
          type="button"
          onClick={() => {
            markRead(items.map((n) => n.id));
            setStatus("All notifications marked as read.");
          }}
          aria-disabled={!unread || undefined}
          className={cx(
            "rounded-md px-2 py-1 text-[12.5px] outline-none transition-[color,opacity] duration-200 focus-visible:ring-2 focus-visible:ring-brand/50",
            unread ? "text-brand hover:bg-[color-mix(in_srgb,var(--color-brand)_8%,transparent)]" : "pointer-events-none text-mute opacity-50",
          )}
        >
          Mark all read
        </button>
      </div>

      <div role="tablist" aria-label="Filter" className="relative mx-4 grid grid-cols-2 rounded-lg bg-paper-2 p-0.5">
        <span
          aria-hidden
          className="absolute bottom-0.5 left-0.5 top-0.5 w-[calc(50%-2px)] rounded-[7px] bg-paper shadow-[0_1px_2px_rgb(0_0_0/0.08),inset_0_0_0_1px_color-mix(in_srgb,var(--color-ink)_7%,transparent)] transition-transform duration-500"
          style={{ transform: tab === "unread" ? "translateX(100%)" : "none", transitionTimingFunction: CURVE }}
        />
        {(["all", "unread"] as const).map((t) => (
          <button
            key={t}
            type="button"
            role="tab"
            id={`${tabsId}-${t}`}
            aria-selected={tab === t}
            aria-controls={`${tabsId}-panel`}
            tabIndex={tab === t ? 0 : -1}
            onClick={() => pickTab(t)}
            onKeyDown={(e) => {
              if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
                e.preventDefault();
                const other = t === "all" ? "unread" : "all";
                pickTab(other);
                (e.currentTarget.parentElement?.querySelector(`#${CSS.escape(`${tabsId}-${other}`)}`) as HTMLElement | null)?.focus();
              }
            }}
            className={cx(
              "relative z-10 flex h-7 items-center justify-center gap-1.5 rounded-[7px] text-[12.5px] outline-none transition-colors duration-300 focus-visible:ring-2 focus-visible:ring-brand/50",
              tab === t ? "text-ink" : "text-mute hover:text-ink",
            )}
          >
            {t === "all" ? "All" : "Unread"}
            {t === "unread" && unread > 0 && <span className="text-[11.5px] tabular-nums text-mute">{unread}</span>}
          </button>
        ))}
      </div>

      <div id={`${tabsId}-panel`} role="tabpanel" aria-labelledby={`${tabsId}-${tab}`} className="mt-2 min-h-0 flex-1 overflow-y-auto pb-2 [scrollbar-width:thin]">
        {groups.length === 0 ? (
          <div key={tab} className="flex flex-col items-center px-6 py-12 text-center" style={{ animation: `kit-nc-in .4s ${CURVE}` }}>
            <span className="grid h-11 w-11 place-items-center rounded-full bg-paper-2 text-mute">
              <BellIcon className="h-5 w-5" />
            </span>
            <p className="mt-4 text-[14px] font-medium text-ink">{tab === "unread" ? "You're all caught up" : "No notifications yet"}</p>
            <p className="mt-1 text-[12.5px] text-mute">{tab === "unread" ? "New activity will show up here." : "When something happens, you'll see it here."}</p>
          </div>
        ) : (
          <ul ref={list} key={tab} onKeyDown={onListKey} aria-label={tab === "all" ? "All notifications" : "Unread notifications"}>
            {groups.map((g, gi) => (
              <li key={g.label} style={{ animation: `kit-nc-in .4s ${CURVE} ${gi * 40}ms both` }}>
                <p className="px-4 pb-1 pt-3 text-[11.5px] font-medium text-mute">{g.label}</p>
                <ul>
                  {g.items.map((n) => (
                    <li key={n.id} className="group relative px-1.5">
                      <button
                        type="button"
                        data-nc-item
                        onClick={() => {
                          markRead([n.id]);
                          onOpenItem?.(n.read ? n : { ...n, read: true });
                        }}
                        className="flex w-full gap-3 rounded-[10px] py-2.5 pl-2.5 pr-9 text-left outline-none transition-colors duration-200 hover:bg-paper-2 focus-visible:bg-paper-2 focus-visible:ring-2 focus-visible:ring-brand/50"
                      >
                        {n.actor ? (
                          <Avatar name={n.actor.name} src={n.actor.src} size="sm" />
                        ) : (
                          <span aria-hidden className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-paper-2 text-mute">
                            <BellIcon className="h-4 w-4" />
                          </span>
                        )}
                        <span className="min-w-0 flex-1">
                          <span className={cx("block text-[13px] leading-snug transition-colors duration-300", n.read ? "text-ink-2" : "text-ink")}>
                            {!n.read && <span className="sr-only">Unread: </span>}
                            {n.title}
                          </span>
                          {n.body && <span className="mt-0.5 line-clamp-2 block text-[12.5px] leading-snug text-mute">{n.body}</span>}
                          <span className="mt-1 block text-[11.5px] tabular-nums text-mute">{ago(n.time)}</span>
                        </span>
                      </button>
                      {/* The dot doubles as "mark as read". It fades out once read. */}
                      <button
                        type="button"
                        aria-label={`Mark "${n.title}" as read`}
                        tabIndex={n.read ? -1 : 0}
                        aria-hidden={n.read || undefined}
                        onClick={(e) => {
                          markRead([n.id]);
                          setStatus("Marked as read.");
                          (e.currentTarget.previousElementSibling as HTMLElement | null)?.focus();
                        }}
                        className={cx(
                          "absolute right-3 top-3.5 grid h-6 w-6 place-items-center rounded-full outline-none transition-[opacity,transform] duration-500 focus-visible:ring-2 focus-visible:ring-brand/50",
                          n.read ? "pointer-events-none scale-50 opacity-0" : "opacity-100 hover:scale-110",
                        )}
                        style={{ transitionTimingFunction: CURVE }}
                      >
                        <span className="h-2 w-2 rounded-full bg-brand" />
                      </button>
                    </li>
                  ))}
                </ul>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

/* ---------- bell + popover ---------- */

/**
 * A bell with an unread count that opens a notification panel. Switch between All and Unread, read
 * them grouped by day, and mark one or all as read: the blue dot fades out. The bell rings when new
 * ones arrive. Arrow keys move through the list.
 */
export function NotificationCenter({
  notifications,
  defaultNotifications = [],
  onNotificationsChange,
  onOpenItem,
  now: nowProp,
  locale,
  align = "end",
  label = "Notifications",
  className,
}: NotificationCenterProps) {
  const [inner, setInner] = useState(defaultNotifications);
  const items = notifications ?? inner;
  const unread = items.filter((n) => !n.read).length;
  const [opened, setOpened] = useState(() => new Date());

  // Ring the bell when the unread count goes up.
  const [prev, setPrev] = useState(unread);
  const [rings, setRings] = useState(0);
  if (prev !== unread) {
    if (unread > prev) setRings((r) => r + 1);
    setPrev(unread);
  }

  const update = (next: NotificationEntry[]) => {
    if (notifications === undefined) setInner(next);
    onNotificationsChange?.(next);
  };

  return (
    <span className="kit-nc inline-flex">
      <style href="asta-notification-center" precedence="asta">{KEYFRAMES}</style>
      <Popover
        align={align}
        label={label}
        className="w-[380px] !p-0"
        onOpenChange={(o) => {
          if (o) setOpened(new Date());
        }}
        trigger={(props, open) => (
          <button
            type="button"
            {...props}
            aria-label={unread ? `${label}, ${unread} unread` : label}
            className={cx(
              "relative grid h-9 w-9 place-items-center rounded-lg text-ink-2 outline-none transition-colors duration-200 hover:bg-paper-2 hover:text-ink focus-visible:ring-2 focus-visible:ring-brand/50",
              open && "bg-paper-2 text-ink",
              className,
            )}
          >
            <span key={rings} className="grid origin-[50%_15%] place-items-center" style={rings ? { animation: `kit-nc-ring .9s ${CURVE}` } : undefined}>
              <BellIcon className="h-[18px] w-[18px]" />
            </span>
            {unread > 0 && (
              <span
                aria-hidden
                className="absolute -right-0.5 -top-0.5 flex h-[18px] min-w-[18px] items-center justify-center overflow-hidden rounded-full bg-brand px-1 text-[10.5px] font-medium tabular-nums text-white shadow-[0_0_0_2px_var(--color-paper)]"
                style={{ animation: `kit-nc-badge .35s ${CURVE}` }}
              >
                <span key={unread} className="block" style={{ animation: `kit-nc-count .35s ${CURVE}` }}>
                  {unread > 99 ? "99+" : unread}
                </span>
              </span>
            )}
          </button>
        )}
      >
        <Panel items={items} update={update} onOpenItem={onOpenItem} now={nowProp ?? opened} locale={locale} label={label} />
      </Popover>
    </span>
  );
}

export default NotificationCenter;
